import React from 'react';
// NOTE: framer-motion import has been removed as it causes 'Module not found' errors.

// Icon component for the logo, using inline SVG (simulated Lucide Leaf)
const IconLeaf = (props) => (
  <svg {...props} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="lucide lucide-leaf">
    <path d="M11 20A7 7 0 0 1 9.85 15.3l-1.42-1.42a4 4 0 0 0-.84 4.51c-.68 1.4-1.9 2.1-3.14 2.1-1 0-1.87-.27-2.7-.87 1.25.75 2.5 1.15 3.84 1.15 3.5 0 6-3.72 6-8s-2.5-8-6-8c-1.34 0-2.59.4-3.84 1.15.83-.6 1.7-.87 2.7-.87 1.24 0 2.46.7 3.14 2.1a4 4 0 0 0 .84 4.51l1.42 1.42A7 7 0 0 1 11 20z"/>
    <path d="M19 14c1.47 0 2.91.48 4 1.41-1.09-.93-2.53-1.41-4-1.41z"/>
  </svg>
);

// Component for the 3D-styled logo (Now using standard H1 and CSS transitions)
const Logo3D = () => (
    <h1 // Changed from motion.h1
        className="text-3xl sm:text-4xl font-black z-20 transition duration-300 transform hover:scale-[1.02] hover:rotate-1"
        style={{
            // CSS text shadows create the layered 3D effect: light green face, darker green depth
            textShadow: '2px 2px 0 #15803d, 4px 4px 0 #059669, 6px 6px 0 #065f46',
            letterSpacing: '1px',
            cursor: 'pointer',
        }}
    >
        <span className="flex items-center gap-2 text-green-100">
            <IconLeaf 
                className="w-8 h-8 text-green-300" 
                // Add a drop shadow to the icon to match the text depth
                style={{ filter: 'drop-shadow(2px 2px 0 #065f46)' }} 
            />
            EcoPackAI
        </span>
    </h1>
);

// Component to load the Inter font
const FontLoader = () => (
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;900&display=swap" rel="stylesheet" />
);


export default function HomePage() {
  return (
    <>
    <FontLoader />
    {/* Custom Styles for background animation to replace framer-motion logic */}
    <style>{`
        @keyframes pulse-slow {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
        }
        .animate-slow-pulse {
            animation: pulse-slow 12s infinite ease-in-out;
        }
      `}</style>

    <div className="min-h-screen flex flex-col bg-gradient-to-br from-green-50 via-white to-green-100 text-gray-800 font-['Inter']">
      
      {/* Animated Background Blobs (Changed from motion.div to standard div with CSS animation) */}
      <div
        className="absolute top-0 left-0 w-72 h-72 bg-green-300 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"
      ></div>
      <div
        className="absolute bottom-0 right-0 w-96 h-96 bg-emerald-400 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-slow-pulse"
      ></div>

      {/* Navbar with 3D Logo */}
      <header className="flex justify-between items-center px-10 py-6 z-10">
        <Logo3D /> {/* <- 3D Logo Component Added Here */}
        <nav className="space-x-6 text-lg font-medium">
          <a href="#about" className="hover:text-green-600 transition">About</a>
          <a href="#features" className="hover:text-green-600 transition">Features</a>
          <a href="#contact" className="hover:text-green-600 transition">Contact</a>
        </nav>
      </header>

      {/* Hero Section (motion components replaced with standard elements) */}
      <section className="flex flex-col justify-center items-center text-center mt-24 px-6 z-10">
        <h2 // Changed from motion.h2
          className="text-5xl sm:text-6xl font-extrabold text-green-800 opacity-0 animate-fade-in-up-1"
        >
          EcoPackAI
        </h2>
        <p // Changed from motion.p
          className="mt-4 text-xl sm:text-2xl text-gray-700 max-w-2xl opacity-0 animate-fade-in-up-2"
        >
          AI-Powered Sustainable Packaging Recommendations
        </p>
        <div // Changed from motion.div
          className="mt-8 opacity-0 animate-fade-in-up-3"
        >
          <button className="px-8 py-3 bg-green-600 text-white text-lg rounded-full shadow-lg transition-all hover:bg-green-700 hover:scale-105">
            Get Started
          </button>
        </div>
        
        {/* Custom Keyframes for staggered entry animation (to replace framer-motion) */}
        <style>{`
            @keyframes fadeInUp {
                from { opacity: 0; transform: translateY(20px); }
                to { opacity: 1; transform: translateY(0); }
            }
            .animate-fade-in-up-1 {
                animation: fadeInUp 1s ease-out forwards;
            }
            .animate-fade-in-up-2 {
                animation: fadeInUp 1s ease-out forwards 0.3s;
            }
            .animate-fade-in-up-3 {
                animation: fadeInUp 1s ease-out forwards 0.8s;
            }
        `}</style>
      </section>

      {/* About Section */}
      <section id="about" className="py-24 px-10 text-center bg-white/60 backdrop-blur-sm mt-16">
        <h3 className="text-3xl font-bold text-green-700 mb-6">About EcoPackAI</h3>
        <p className="max-w-3xl mx-auto text-lg text-gray-700">
          EcoPackAI helps businesses choose eco-friendly, cost-effective packaging materials 
          using AI-driven recommendations. Our mission is to reduce carbon footprints and promote 
          sustainable packaging decisions across industries.
        </p>
      </section>

      {/* Features Section */}
      <section id="features" className="py-20 px-8 bg-green-50 text-center">
        <h3 className="text-3xl font-bold text-green-700 mb-10">Key Features</h3>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10 max-w-6xl mx-auto">
          {[
            {
              title: "AI-Powered Insights",
              desc: "Smart algorithms recommend the most sustainable and cost-efficient packaging materials.",
            },
            {
              title: "Eco Material Database",
              desc: "Access verified data on 20+ biodegradable and recyclable materials.",
            },
            {
              title: "Visual Dashboards",
              desc: "Compare cost vs. CO₂ footprint with easy-to-read charts and exports.",
            },
            {
              title: "Sustainability Impact",
              desc: "Achieve up to 30% reduction in environmental impact per packaging choice.",
            },
          ].map((f, i) => (
            <div // Changed from motion.div
              key={i}
              className="p-6 bg-white shadow-lg rounded-2xl transition-all duration-300 hover:shadow-2xl hover:scale-[1.05]"
            >
              <h4 className="text-2xl font-semibold text-green-700 mb-2">{f.title}</h4>
              <p className="text-gray-600">{f.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Call To Action */}
      <section className="py-20 bg-green-600 text-white text-center">
        <h3 // Changed from motion.h3
          className="text-3xl font-bold mb-6 transition duration-700"
        >
          Ready to make packaging sustainable?
        </h3>
        <button // Changed from motion.button
          className="bg-white text-green-700 px-8 py-3 text-lg font-semibold rounded-full shadow-md transition hover:bg-gray-100 hover:scale-110"
        >
          Get Started
        </button>
      </section>

      {/* Footer */}
      <footer id="contact" className="py-6 bg-green-900 text-white text-center text-sm">
        © {new Date().getFullYear()} EcoPackAI | Designed with 💚 for a greener planet
      </footer>
    </div>
    </>
  );
}
